contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public function driving the property check. We take an amount and make both calls.
    function run(uint amount) public payable {
        require(true);

        // Observe initial public state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        address owner = c.owner(); if (__ESBMC_reverted()) return;

        // Perform the state-changing calls each as a top-level statement and capture revert flags
        bool revertedWithdraw;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedWithdraw = true;
        } else {
            revertedWithdraw = false;
        }

        bool revertedWithdrawAll;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedWithdrawAll = true;
        } else {
            revertedWithdrawAll = false;
        }

        // Read post-state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Single assert encoding both cases depending on ownership
        assert(
            // If caller is not owner: both calls must revert and no state change
            (address(this) != owner && revertedWithdraw && revertedWithdrawAll && afterBalance == beforeBalance && afterDeposits == beforeDeposits)
            ||
            // If caller is owner: calls may succeed, but balance cannot increase and depositsCount cannot decrease
            (address(this) == owner && afterBalance <= beforeBalance && afterDeposits >= beforeDeposits)
        );
    }

    // Allow receiving Ether if C sends funds back to this contract during tests
    receive() external payable {}
}

